=== usb_serial.ino ===
   1| // Lab 5: serial ID responder
   2| // Answers ID?, SUM? and HEX? at 9600 baud; unknown commands get ERR.
   3| // Line endings: '\r' is dropped, '\n' ends the command.
   4| 
   5| const char STUDENT_ID[] = "<student_id>";
   6| 
   7| char cmd[16];
   8| byte n = 0;
   9| 
  10| int idSum() {
  11|   int t = 0;
  12|   for (byte i = 0; STUDENT_ID[i]; i++) t += STUDENT_ID[i] - '0';
  13|   return t;
  14| }
  15| 
  16| void handle() {
  17|   if (strcmp(cmd, "ID?") == 0)        Serial.println(STUDENT_ID);
  18|   else if (strcmp(cmd, "SUM?") == 0)  Serial.println(idSum());
  19|   else if (strcmp(cmd, "HEX?") == 0)  Serial.println(strtoul(STUDENT_ID, NULL, 10), HEX);
  20|   else                                Serial.println("ERR");
  21| }
  22| 
  23| void setup() {
  24|   Serial.begin(9600);
  25| }
  26| 
  27| void loop() {
  28|   while (Serial.available()) {
  29|     char c = Serial.read();
  30|     if (c == '\r') continue;
  31|     if (c == '\n') {
  32|       cmd[n] = '\0';
  33|       if (n > 0) handle();
  34|       n = 0;
  35|     } else if (n < sizeof(cmd) - 1) {
  36|       cmd[n++] = c;
  37|     }
  38|   }
  39| }
</student_code>
